# SPDX-License-Identifier: Apache-2.0
"""Bake small arm-contact samples from the same saved poses as the rendered skin."""

import bpy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CLIPS = ["Idle", "Swim", "Turn_Left", "Turn_Right", "Sing", "Wave", "Hurt", "Throw"]
SAMPLES = 32


def export_contacts(rig):
    previous_action = rig.animation_data.action
    previous_frame = bpy.context.scene.frame_current
    lines = [
        "// SPDX-License-Identifier: Apache-2.0",
        "// Generated by tools/blender/export_sabrina_contacts.py. Re-export the saved Sabrina .blend.",
        "#pragma once",
        "namespace reef::sabrina_contacts {",
        "struct Point {",
        "    float x, y, z;",
        "};",
        f"inline constexpr int samples = {SAMPLES};",
        f"inline constexpr float palm_offset = {rig.data.bones['Hand_R'].length * .5:.8f}f;",
        "// Clip order matches SabrinaPose. Points: shoulder, elbow, fingertips, each side; right palm.",
        "// clang-format off",
        f"inline constexpr Point arms[8][{SAMPLES}][7] = {{",
    ]
    for clip in CLIPS:
        rig.animation_data.action = bpy.data.actions[clip]
        start, end = rig.animation_data.action.frame_range
        lines.append("    { // " + clip)
        for i in range(SAMPLES):
            time = start + (end - start) * i / (SAMPLES - 1)
            bpy.context.scene.frame_set(int(time), subframe=time - int(time))
            points = []
            for side in ("L", "R"):
                for name, endpoint in [
                    ("UpperArm", "head"),
                    ("Forearm", "head"),
                    ("Hand", "tail"),
                ]:
                    p = getattr(rig.pose.bones[name + "_" + side], endpoint)
                    points.append(
                        "{"
                        + ", ".join(
                            f"{v:.6f}f" for v in (p.x * 0.88, p.z * 0.88, -p.y * 0.88)
                        )
                        + "}"
                    )
            hand = rig.pose.bones["Hand_R"]
            p = (hand.head + hand.tail) * 0.5
            points.append(
                "{"
                + ", ".join(f"{v:.6f}f" for v in (p.x * 0.88, p.z * 0.88, -p.y * 0.88))
                + "}"
            )
            lines.append("        {" + ", ".join(points) + "},")
        lines.append("    },")
    lines.extend(
        ["};", "// clang-format on", "} // namespace reef::sabrina_contacts", ""]
    )
    target = ROOT / "src/simulation/generated/sabrina_contacts.h"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines))
    rig.animation_data.action = previous_action
    bpy.context.scene.frame_set(previous_frame)
